#!/usr/bin/env python3
"""새 배경 규칙(평평한 종이 한 장) 일괄 재생성 작업 목록 만들기 -> jobs_bg_batch.json"""
import json, os
HERE = os.path.dirname(os.path.abspath(__file__))
calib = json.load(open(os.path.join(HERE, 'jobs_bg_calib.json')))
NEG_IN = calib[0]['negative']
NEG_OUT = NEG_IN.replace('wavy layers, torn paper bands, layered waves on wall, wavy bands on floor, ', 'decorative wavy bands in the sky, many horizontal stripes, ')
NEG_TOP = NEG_IN.replace('layered waves on wall, wavy bands on floor, ', 'many scattered small pieces, ') + ', wall, horizon line'
GRAIN = ('soft warm paper grain, a gentle darker floor band with a soft shadow line where wall meets floor, '
         'one small warm accent (lamp glow / window light) allowed. ')
COMMON = ('A calm flat paper-cut picture-book background in a strict handcraft design system: the whole image is ONE flat sheet of colored paper '
          'with a fine subtle paper grain, in only one or two soft muted tones, filling the ENTIRE image edge to edge. ')
OBJ = ('Only two or three simple meaningful objects, each cut from a few completely flat die-cut pieces with clean edges, no outlines, raised slightly '
       'so each casts a soft narrow warm dark-brown paper shadow onto the sheet behind it. Straight-on orthographic front view, zero perspective, '
       'chunky simple shapes. Depth comes only from: back sheet, one middle layer, and soft drop shadows. '
       'Very large empty open space so characters will stand big in front. ')
INDOOR = (COMMON + 'The back wall is a single flat plain sheet and the floor is a single flat plain sheet below a straight horizontal line - NO wavy bands, '
          'NO torn-paper strips, NO layered waves, NO patches or blotches on walls or floors. ' + OBJ + GRAIN)
OUTDOOR = (COMMON + 'The sky is a single flat plain sheet with NO decorative bands or stripes. Real layered things such as hills, water or clouds may be '
           'two or three large smooth cut-paper layers, and nothing else is layered. NO patches or blotches. ' + OBJ + GRAIN.replace('a gentle darker floor band with a soft shadow line where wall meets floor, ', 'a soft shadow line under each paper layer, '))
TOP = (COMMON + 'Seen straight down from above, the ground is a single flat plain sheet - NO wavy bands, NO torn-paper strips, NO patches or blotches. '
       'Only a few simple meaningful objects, each cut from a few completely flat die-cut pieces with clean edges, no outlines, each casting a soft narrow warm dark-brown paper shadow. '
       'Zero perspective, chunky simple shapes, very large empty open space in the middle so characters can stand big. soft warm paper grain. ')
NIGHT = ' Gentle but BRIGHT readable night: mid-tone blues, never black or dark.'
S = {}  # name -> (kind, scene)
def add(n, kind, scene): S[n] = (kind, scene)

add('ag_bg_door', 'out', 'a low snowy scene in soft winter pastels: a plain pale blue-grey sky sheet, a flat white snow ground sheet, and one brown soil bank with a thin white snow cap at the LEFT with a big plain arched doorway in it glowing warm amber inside (a single doorway, only two frame layers). No snowflakes clutter. The right half and the whole middle are empty snow and sky.')
add('br_bg_house_low', 'in', 'the plain wooden wall of a house at night seen from outside: one flat plain dark-blue-grey wall sheet and a flat sage grass sheet at the bottom. Only three objects: a round cream moon at the upper left, one tall window on the right glowing warm amber (empty inside), and nothing else. No decorative bands on the wall.' + NIGHT)
add('br_bg_house_pov', 'in', 'a plain warm room seen from a window: one flat plain cream wall sheet and a flat plain wood floor sheet. Only three objects: a dark wooden window frame with a centre bar framing the whole view edge to edge, one plain arched orange doorway on the right wall, and one long plain wooden table across the lower middle with a small pile of gold coins, a plate of food and a plate of fruit on it. No mountains, no pictures, no frames on the wall. Warm lamp glow.')
add('fc_bg_crane_room', 'in', 'a tall plain cream room: one flat plain cream wall sheet and a flat plain honey wood floor sheet. Only three objects: one window on the LEFT showing a small flat blue pond outside, one small empty wooden table at the centre-right, and two plain wooden ceiling beams across the top. The floor is empty.')
add('fc_bg_high', 'top', 'a high view down onto a flat plain warm wood floor sheet (plank lines very faint). Only two objects: one big round soft-red rug with a single gold ring in the centre, and one round wooden table standing on the middle of the rug with its top empty. Nothing else.')
add('fc_bg_kitchen', 'in', 'a cosy burrow kitchen: one flat plain light-brown earthen wall sheet with a gently arched top edge (only one extra arch layer) and a flat plain wood floor sheet. Only three objects: a round window with a cross frame at the upper right, a wooden shelf with four little clay jars at the upper left, and one big empty floor space at the centre for a big pot.')
add('gl_bg_bed_side', 'in', 'a cosy bedroom: one flat plain wall sheet in warm honey tone and a flat plain plank floor sheet. Only two objects: one window at the far LEFT, and a plain short horizontal log-beam strip at the top of the wall. The whole middle and right floor are empty.')
add('gl_bg_kitchen', 'in', 'a cabin kitchen: one flat plain warm honey wall sheet and a flat plain plank floor sheet. Only three objects: a dark iron stove with a small warm fire, a stovepipe and a black pot at the LEFT; a window at the upper right with soft sun outside; a wall shelf with three plates in big, medium and small sizes in the upper middle. Open floor in the middle.')
add('gl_bg_table', 'top', 'a high view looking straight down at a big warm wooden table top with very faint plank lines filling the whole image: one flat plain honey wood sheet, completely empty, with only a thin slightly darker rim strip along the edges. Nothing else, no wall.')
add('a3_sky', 'out', 'ONLY a warm autumn afternoon sky: one flat plain pale gold sheet, lighter near the sun. A round layered paper sun (three stacked circles) in the UPPER LEFT with two soft concentric halo rings (cream, pale apricot). Nothing else, no clouds bands, no hills. The sky continues to the bottom edge.')
add('scene_b_kitchen', 'in', 'a traditional Korean earthen kitchen (buoak) at night: one flat plain clay-brown back wall sheet and a flat plain dark packed-earth floor sheet. Only three objects: a small wooden lattice window with a moonlit indigo sky at the upper middle, one thick plain ceiling beam across the top, and a dark wooden post at each side. The left floor near the wall is open for a stove; the right side near the wall is open for a door. No stove, no door, no shelves.' + NIGHT)
add('sw_bg_high', 'top', 'a view looking straight down from high in the sky onto the countryside: one flat plain pale sage ground sheet, with only four things: one winding light dirt road from the bottom centre up to the top, one little house seen from above on the right (cream walls, golden roof), three round pine-tree crowns, and a soft white cloud corner in each of the two top corners. Plenty of empty ground.')
add('sm_bg_hill_dusk', 'out', 'a mountain pass at sunset: one flat plain warm peach sky sheet with NO bands, two smooth cut-paper mountain layers behind (one far, one near), a flat plain ground sheet with a plain light path, one big grey rock beside the path on the left-centre, and a small wooden signpost on the right. Plenty of empty space. No people.')
add('sm_bg_kitchen', 'in', 'a rich family traditional Korean kitchen: one flat plain warm wall sheet and a flat plain floor sheet. Only three objects: one clay stove with two iron cauldrons at the LEFT, one wooden shelf on the wall in the middle-left, and one low table with a plate of white rice cakes (tteok) at the RIGHT. Open floor in the middle. No people.')
add('ud_bg_cabin', 'in', 'a cosy cottage in winter: one flat plain warm brown plank wall sheet and a flat plain warm wooden floor sheet. Only three objects: a small window at the upper left showing a soft blue snowy evening, a black iron stove on the right with a warm amber fire glow, and one soft red oval rug in the middle of the floor. Bright and warm.')
add('ud_bg_swamp', 'out', 'a wide quiet marsh: a plain pale grey-green sky sheet with two flat clouds, one sage far bank layer, one calm blue-grey water layer with just a few ripple lines, small reeds at both edges and two round lily pads. Plenty of open water in the middle.')
