add('wg_bg_inside_door', 'in', 'the inside of a farmhouse: one flat plain cream wall sheet and a flat plain wood floor sheet. Only one object: a big plain round-topped wooden door in the centre with one big latch and a small round peek window near its top. Nothing else. Open floor.')
add('wg_bg_kitchen', 'in', 'a cosy farmhouse kitchen: one flat plain cream wall sheet and a flat plain wood floor sheet. Only three objects: a window at the left with a sunny meadow outside, a stove with a kettle at the right, and a tall grandfather clock against the back wall in the middle-right. Open floor in the middle.')
add('wg_bg_messy', 'in', 'the same plain farmhouse room, messy and EMPTY: one flat plain cream wall sheet and a flat plain wood floor sheet. Only three objects: a tall grandfather clock at the left, one toppled stool, and one rumpled quilt on the floor in the middle. No animals, no other clutter.')
add('wg_bg_shadow', 'in', 'a shadow-play screen: one big flat plain glowing cream-white paper screen filling the whole frame lit warmly from behind (very even, no darker blotches), a thin darker brown wooden frame strip at the edges, and a plain wooden table edge strip at the bottom. Nothing else.')
add('rh_bg_bed', 'in', "a close-up of a grandma's bed: one flat plain warm wall sheet and a flat plain floor strip at the bottom. Only three objects: a plain wooden headboard with a round-edged quilt in lavender and cream and one big pillow, one big EMPTY plain wooden picture frame on the wall at the right, and one small wooden night table at the left.")
add('rh_bg_flowers', 'top', 'a high view looking down on a sunny meadow: one flat plain soft sage grass sheet, with only about twelve well-spaced round-petal flowers (red, yellow and blue) in three loose groups near the edges, one tiny pale path strip at the bottom, and a few tree crowns along the top edge. Very large empty grass in the middle.')
add('rh_bg_kitchen', 'in', 'a cosy farmhouse kitchen: one flat plain warm cream wall sheet and a flat plain wood floor sheet. Only three objects: a window at the right showing a sunny garden, a stove at the left, and a wooden table with a cloth in the middle with its table top flat and clear. Open floor.')
add('rh_bg_room', 'in', "grandma's bedroom: one flat plain warm cream wall sheet and a flat plain wood floor sheet. Only three objects: a tall wooden wardrobe at the left, a bed at the right, and a window in the middle of the wall. Open floor in the middle with one small lavender rug.")
add('rh_bg_table', 'in', "grandma's cottage at tea time: one flat plain warm peach wall sheet and a flat plain wood floor sheet. Only three objects: a table with a cloth in the middle, a window with a sunset glow at the upper right, and a small wall shelf of jars at the upper left. Table top clear.")
add('mj_bg_field', 'out', 'a wide Korean farm field: a plain pale blue sky sheet, one flat plain brown earth ground sheet with only three or four wide plain furrow strips with a few small green sprouts, a small thatched cottage on the left, one low stone wall and one persimmon tree. Field clear in the middle.')
add('mj_bg_hall', 'in', "a rich man's wooden hall seen straight-on: one flat plain cream wall sheet and a wide flat honey-wood floor sheet. Only three objects: a folding screen with a plain pine tree at the back centre, a pair of lanterns hanging, and a low table at the left. Floor clear.")
add('mj_bg_hallwide', 'in', 'a grand wooden hall seen from further away: one flat plain cream wall sheet and a very wide flat honey-wood floor sheet. Only three objects: two tall plain pillars at the far left and right, a folding screen at the back centre, and two hanging lanterns. Big open space in the middle for a crowd.')
add('mj_bg_jarfront', 'in', 'a wooden porch: one flat plain warm honey wall sheet with a single plain paper door at the RIGHT, and a wide flat plain wooden porch floor sheet below with a wide empty flat area in the middle to place a jar. Nothing else, no scattered pieces.')
add('kj_bg_field', 'top', 'a high view looking down on a dry field: one flat plain warm brown soil sheet with only five or six round grey stones, two small grass tufts, and a thin pale grass rim around the edge. Soil clear in the middle.')
add('kj_bg_loom', 'in', 'inside a Korean room: one flat plain cream wall sheet and a flat plain honey wood floor sheet. Only three objects: a paper-screen sliding door at the left with a soft lantern glow, a wooden folding screen at the right, and a clear plain floor space in the middle for a loom. If a window is shown it is a plain window with a plain pale sky and two flat hills only.')
add('hb_bg_eaves', 'out', 'a low view looking up from the yard: one flat plain pale blue sky sheet with a few round clouds, the thatched eaves of a hut as one straw-gold layer across the top with a small swallow nest under the eaves in the centre top, and one bare branch at the side. Open sky.')
add('hb_bg_sky_autumn', 'out', 'a wide empty autumn sky: one flat plain pale peach sky sheet with NO horizontal bands, two or three soft round clouds, a few golden leaves floating, one faint distant hill layer along the bottom, a small sun at the upper left.')
add('hb_bg_sky_spring', 'out', 'a wide empty spring sky: one flat plain pale sky-blue sheet with NO horizontal bands, two or three soft round white clouds, a few flower petals floating, one faint distant green hill layer along the bottom, a small sun at the upper left.')
add('mg_bg_belltower', 'out', 'a mountain temple bell pavilion at night, low view: one flat plain mid-blue night sky sheet with a cream moon, a tiled roof across the top, two wooden pillars, a huge bronze temple bell hanging in the middle and a wooden bell hammer log hanging on ropes beside it, with a flat plain ground strip at the bottom. No bands in the sky.' + NIGHT)
add('mg_bg_nest', 'top', 'a high view looking straight down into a round magpie nest of twigs on a big pine branch: one flat plain pale peach background sheet, one thick pine branch across the middle with only two or three small needle clusters, and a round twig nest in the middle with a soft lined bowl clear in the middle. Little else.')
add('mg_bg_paperdoor', 'in', 'a close-up of a big traditional Korean paper door: one flat plain glowing cream paper surface lit warmly from behind (even, no shadows), a simple wooden lattice of a few straight bars, and a dark wooden frame around it. Nothing behind it, no mountains.' + NIGHT)
add('mg_bg_path', 'out', 'a Korean mountain path in autumn: a flat plain pale peach sky sheet with two round clouds, only two smooth hill layers in maple-red and honey, a few sparse maple trees, and one winding sandy path across the middle. Open path, plenty of empty space.')
add('hg_bg_cage', 'in', "a dim corner of a witch's cottage: one flat plain warm wall sheet and a flat plain wooden floor sheet. Only three objects: a black iron bird cage with an open front at the LEFT, a small candle with a warm glow in the middle, and one small wall shelf behind. Cage door area clear. Dim and warm.")
add('hg_bg_ground', 'top', 'a high view looking straight down at a forest floor: one flat plain warm brown soil sheet with only about ten fallen leaves (cream, honey, brown), three small stones and two ferns, mostly near the edges. Floor clear in the middle.')
add('cd_bg_hearth', 'in', 'a small stone hearth: one flat plain warm cream wall sheet and a flat plain wood floor sheet. Only three objects: a stone fireplace with a gentle orange ember glow in the middle, a small three-legged stool at the left, and nothing else. Clean floor, no soot patches. Hearth area clear. Dim, warm and tender.')
add('cd_bg_parlor', 'in', "a stepmother's elegant parlour: one flat plain cream wall sheet and a flat plain warm wood floor sheet. Only three objects: a pink velvet sofa on the left, a big window in the middle, and a round table on the right. One small floral rug in the middle of the floor. Open floor.")
add('sm_bg_room2', 'in', 'a plain Korean room seen straight-on: one flat plain warm cream wall sheet and a flat plain yellow-brown floor sheet (a single flat floor, no border lines). Only four objects: one closed paper sliding door (hanji with a simple lattice) in the centre of the wall, one small wooden chest at the LEFT, one folded quilt on the floor in front of the chest, and one small low wooden lamp stand with a plain empty oil dish at the RIGHT of the wall near the door (no flame). Nothing else, no pine trees, no mountains. Open floor.')
add('sm_bg_door2', 'in', 'a close-up of a big closed Korean sliding paper door filling the middle: one flat plain cream hanji paper pair of panels with a simple wooden lattice frame of a few straight bars and a small iron ring latch at the centre seam, on one flat plain warm wall sheet on both sides (no mountains), and a flat plain floor strip at the bottom. Nothing else.')

jobs = []
for n, (kind, scene) in S.items():
    base = {'in': INDOOR, 'out': OUTDOOR, 'top': TOP}[kind]
    neg = {'in': NEG_IN, 'out': NEG_OUT, 'top': NEG_TOP}[kind]
    jobs.append({'name': n + '_v2', 'w': 1760, 'h': 992, 'cfg': 3.0, 'key': False, 'trim': False, 'negative': neg,
                 'prompt': base + 'Scene: ' + scene + ' Soft muted low-saturation picture-book pastels, gentle warm light. No characters, no text, no watermark.'})
json.dump(jobs, open(os.path.join(HERE, 'jobs_bg_batch.json'), 'w'), ensure_ascii=False, indent=1)
print(len(jobs))
